import { describe, it, expect, beforeEach } from 'vitest';
import { WatchlistStore } from '../app/watchlist-store';

const mk = (id: number, watched: boolean) => ({
  id,
  title: 'M' + id,
  release_date: '2020-01-01',
  poster_path: null,
  watched,
});

describe('WatchlistStore.clearWatched', () => {
  let store: WatchlistStore;
  beforeEach(() => {
    localStorage.clear();
    store = new WatchlistStore();
  });

  it('removes watched items and keeps unwatched ones', () => {
    store.add(mk(1, false));
    store.add(mk(2, true));
    store.add(mk(3, true));
    store.add(mk(4, false));
    store.clearWatched();
    expect(store.items().map((i) => i.id)).toEqual([1, 4]);
  });

  it('persists the cleared state', () => {
    store.add(mk(1, true));
    store.clearWatched();
    const fresh = new WatchlistStore();
    expect(fresh.items()).toEqual([]);
  });

  it('is safe on an empty list', () => {
    store.clearWatched();
    expect(store.items()).toEqual([]);
  });
});

